"""Killable single-render child process; request file is generated by the worker."""
import json
import sys
from copy import deepcopy
from pathlib import Path

import kari_core.processor  # noqa: F401
from kari_core.core.output_metadata import load_photograph
from kari_core.core.util import get_exif
from kari_core.processor.core import start_process
from kari_core.processor.kari_imprint import _dict_to_imprint_config
from kari_core.shared.assembler import imprint_config_to_processors
from kari_core.shared.layout.layout_engine import compute_layout
from loguru import logger
from PIL import Image

# The child reports a machine-readable failure code on its last stderr line;
# the worker maps it to a public job error and never surfaces anything else.
ERROR_PREFIX = 'KARI_RENDER_ERROR='
ERROR_EXIT_CODE = 3
PUBLIC_RENDER_ERRORS = frozenset({'output_too_large', 'image_too_large', 'unsupported_image'})


def render(request):
    logger.disable('kari_core')
    pixels, metadata = load_photograph(request['source'], max_pixels=request['maxPixels'])
    try:
        config = request['config']
        bounds = compute_layout(_dict_to_imprint_config(deepcopy(config)), pixels.width, pixels.height).canvas
        if bounds.w * bounds.h > request['maxOutputPixels'] or max(bounds.w, bounds.h) > request.get('maxOutputEdge', 16384):
            raise ValueError('output_too_large')
        processors = imprint_config_to_processors(config)
        # Keep the original pixel dimensions, but use a practical JPEG
        # compression preset for generated outputs.  Quality 85 with 4:2:0
        # chroma subsampling materially reduces file size while preserving
        # photographic detail; this is intentionally not a hard 8 MiB cap.
        processors[-1].update(quality=85, subsampling=2)
        start_process(processors, input_path=request['source'], output_path=request['target'], initial_buffer=[pixels],
                      pre_loaded_exif=get_exif(request['source']), output_metadata=metadata)
    finally:
        pixels.close()


def error_code(exc: BaseException) -> str:
    """Map a render exception onto a stable public code (no messages, no paths)."""
    if isinstance(exc, Image.DecompressionBombError):
        return 'image_too_large'
    if isinstance(exc, Image.UnidentifiedImageError):
        return 'unsupported_image'
    if isinstance(exc, ValueError) and str(exc) in PUBLIC_RENDER_ERRORS:
        return str(exc)
    if isinstance(exc, MemoryError):
        return 'image_too_large'
    return 'render_failed'


def main(argv: list[str]) -> int:
    try:
        render(json.loads(Path(argv[1]).read_text()))
    except Exception as exc:
        sys.stderr.write(f'\n{ERROR_PREFIX}{error_code(exc)}\n')
        sys.stderr.flush()
        return ERROR_EXIT_CODE
    return 0


def parse_error(stderr: bytes | str | None) -> str:
    """Return the public code from the child's stderr; ``render_failed`` otherwise."""
    if not stderr:
        return 'render_failed'
    text = stderr.decode('utf-8', 'replace') if isinstance(stderr, bytes) else stderr
    for line in reversed(text.strip().splitlines()):
        line = line.strip()
        if line.startswith(ERROR_PREFIX):
            code = line[len(ERROR_PREFIX):]
            return code if code in PUBLIC_RENDER_ERRORS else 'render_failed'
    return 'render_failed'


if __name__ == '__main__':
    sys.exit(main(sys.argv))
